+  try {
+    await fetch(`http://localhost:${porta}/_teste/reset`, { method: 'POST' });
+    await fetch(`http://localhost:${porta}/_teste/atividades`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({
+        id: 'atv_f4_4',
+        titulo: 'Atividade Já Cancelada',
+        tipo: 'palestra',
+        salaId: 'auditorio',
+        vagas: 50,
